001-operation-receipt.sql:
CREATE TABLE sync_operation_receipt (
  id uuid PRIMARY KEY DEFAULT uuidv7(),
  operation_identifier uuid NOT NULL,
  workspace_identifier uuid NOT NULL,
  actor_identifier varchar(200) NOT NULL,
  operation_name varchar(100) NOT NULL,
  operation_version integer NOT NULL CHECK (operation_version > 0),
  fingerprint varchar(64) NOT NULL CHECK (fingerprint ~ '^[0-9a-f]{64}$'),
  request_created_at timestamptz NOT NULL,
  request_expires_at timestamptz NOT NULL,
  status varchar(8) NOT NULL CHECK (status IN ('accepted', 'rejected')),
  accepted_at timestamptz,
  rejected_at timestamptz,
  result_retained_until timestamptz NOT NULL,
  result jsonb,
  rejection_code varchar(100),
  rejection_message text CHECK (length(rejection_message) <= 1000),
  compacted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  CONSTRAINT sync_operation_receipt_operation_identifier_key UNIQUE (operation_identifier),
  CHECK (request_expires_at > request_created_at),
  CHECK (result_retained_until > coalesce(accepted_at, rejected_at)),
  CHECK (
    (status = 'accepted' AND accepted_at IS NOT NULL AND rejected_at IS NULL
      AND rejection_code IS NULL AND rejection_message IS NULL
      AND (compacted_at IS NOT NULL OR result IS NOT NULL))
    OR
    (status = 'rejected' AND accepted_at IS NULL AND rejected_at IS NOT NULL
      AND result IS NULL AND (compacted_at IS NOT NULL OR
        (rejection_code IS NOT NULL AND rejection_message IS NOT NULL)))
  ),
  CHECK (compacted_at IS NULL OR result IS NULL),
  CHECK (result IS NULL OR octet_length(result::text) <= 1048576)
);

CREATE FUNCTION set_sync_operation_receipt_updated_at()
RETURNS trigger AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_sync_operation_receipt_updated_at
BEFORE UPDATE ON sync_operation_receipt
FOR EACH ROW EXECUTE FUNCTION set_sync_operation_receipt_updated_at();

ALTER TABLE sync_operation_receipt REPLICA IDENTITY FULL;

CREATE INDEX idx_sync_operation_receipt_workspace_identifier_result_retained_until_id
ON sync_operation_receipt (workspace_identifier, result_retained_until, id)
WHERE compacted_at IS NULL;

COMMENT ON TABLE sync_operation_receipt IS 'Immutable application request identity and atomic acceptance evidence with compactable results [domain:collaboration],[team:cueloop],[project:cueloop],[service:sync]';
COMMENT ON COLUMN sync_operation_receipt.id IS 'Immutable synthetic UUID v7 receipt identifier';
COMMENT ON COLUMN sync_operation_receipt.operation_identifier IS 'Client-generated UUID v7 request identity retained across retries and compaction';
COMMENT ON COLUMN sync_operation_receipt.workspace_identifier IS 'Workspace authorized by the application before accepting or reading a receipt';
COMMENT ON COLUMN sync_operation_receipt.actor_identifier IS 'Verified application principal bound to the accepted request';
COMMENT ON COLUMN sync_operation_receipt.operation_name IS 'Registered application operation name';
COMMENT ON COLUMN sync_operation_receipt.operation_version IS 'Version of the registered operation contract';
COMMENT ON COLUMN sync_operation_receipt.fingerprint IS 'Server-derived SHA-256 fingerprint of canonical request data and verified principal';
COMMENT ON COLUMN sync_operation_receipt.request_created_at IS 'Fixed client request creation time';
COMMENT ON COLUMN sync_operation_receipt.request_expires_at IS 'Fixed deadline for first acceptance; accepted retries retain their identity';
COMMENT ON COLUMN sync_operation_receipt.status IS 'Immutable authoritative acceptance or rejection outcome';
COMMENT ON COLUMN sync_operation_receipt.rejected_at IS 'Authority rejection time, or null for an accepted request';
COMMENT ON COLUMN sync_operation_receipt.rejection_code IS 'Application rejection code retained until compaction';
COMMENT ON COLUMN sync_operation_receipt.rejection_message IS 'Application rejection explanation bounded to 1000 characters and retained until compaction';
COMMENT ON COLUMN sync_operation_receipt.accepted_at IS 'Authority acceptance time, committed atomically with application changes';
COMMENT ON COLUMN sync_operation_receipt.result_retained_until IS 'Deadline after which original result bytes may be compacted';
COMMENT ON COLUMN sync_operation_receipt.result IS 'Original application JSON result, or SQL null after compaction';
COMMENT ON COLUMN sync_operation_receipt.compacted_at IS 'Time when result bytes were removed while preserving request identity';
COMMENT ON COLUMN sync_operation_receipt.created_at IS 'Time when the receipt row was created';
COMMENT ON COLUMN sync_operation_receipt.updated_at IS 'Time when receipt storage metadata was last changed';
COMMENT ON COLUMN sync_operation_receipt.deleted_at IS 'Optional soft-deletion metadata; identity remains reserved';

002-execution.sql:
CREATE TABLE sync_execution (
  id uuid PRIMARY KEY DEFAULT uuidv7(),
  workspace_identifier uuid NOT NULL,
  target_identifier uuid NOT NULL,
  requester_identifier varchar(200) NOT NULL,
  action varchar(100) NOT NULL,
  input jsonb NOT NULL CHECK (octet_length(input::text) <= 1048576),
  status varchar(20) NOT NULL DEFAULT 'waiting-owner'
    CHECK (status IN ('waiting-owner', 'executing', 'completed', 'failed', 'recovery-required')),
  executor_identifier uuid,
  lease_identifier uuid,
  fencing_token integer NOT NULL DEFAULT 0 CHECK (fencing_token >= 0),
  lease_expires_at timestamptz,
  next_check_at timestamptz NOT NULL DEFAULT now(),
  observation_reference varchar(200),
  error_message text CHECK (length(error_message) <= 1000),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  CHECK ((executor_identifier IS NULL AND lease_identifier IS NULL AND fencing_token = 0)
    OR (executor_identifier IS NOT NULL AND lease_identifier IS NOT NULL AND fencing_token > 0)),
  CHECK (lease_expires_at IS NULL OR lease_identifier IS NOT NULL),
  CHECK ((status IN ('failed', 'recovery-required') AND error_message IS NOT NULL)
    OR (status NOT IN ('failed', 'recovery-required') AND error_message IS NULL)),
  CHECK (status NOT IN ('completed', 'failed') OR lease_expires_at IS NULL)
);

CREATE FUNCTION set_sync_execution_updated_at()
RETURNS trigger AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_sync_execution_updated_at
BEFORE UPDATE ON sync_execution
FOR EACH ROW EXECUTE FUNCTION set_sync_execution_updated_at();

ALTER TABLE sync_execution REPLICA IDENTITY FULL;

CREATE INDEX idx_sync_execution_workspace_identifier_next_check_at_id
ON sync_execution (workspace_identifier, next_check_at, id)
WHERE deleted_at IS NULL AND status IN ('waiting-owner', 'executing', 'recovery-required');

CREATE INDEX idx_sync_execution_workspace_identifier_created_at_id
ON sync_execution (workspace_identifier, created_at DESC, id DESC)
WHERE deleted_at IS NULL;

COMMENT ON TABLE sync_execution IS 'Accepted application intent and fenced owner execution observations [domain:collaboration],[team:cueloop],[project:cueloop],[service:sync]';
COMMENT ON COLUMN sync_execution.id IS 'Immutable UUID v7 operation identity shared with its acceptance receipt';
COMMENT ON COLUMN sync_execution.workspace_identifier IS 'Application workspace authorized at request acceptance and owner recovery';
COMMENT ON COLUMN sync_execution.target_identifier IS 'Immutable application target identity resolved by the owner integration';
COMMENT ON COLUMN sync_execution.requester_identifier IS 'Verified application actor that submitted the accepted intent';
COMMENT ON COLUMN sync_execution.action IS 'Registered application action interpreted by the execution integration';
COMMENT ON COLUMN sync_execution.input IS 'Immutable bounded application input committed with the acceptance receipt';
COMMENT ON COLUMN sync_execution.status IS 'Execution observation kept separate from immutable request acceptance';
COMMENT ON COLUMN sync_execution.executor_identifier IS 'Stable provider recovery domain pinned by the first owner claim';
COMMENT ON COLUMN sync_execution.lease_identifier IS 'Most recent claim identity retained for idempotent report retries';
COMMENT ON COLUMN sync_execution.fencing_token IS 'Monotonically increasing claim generation used to reject stale reports';
COMMENT ON COLUMN sync_execution.lease_expires_at IS 'Authority-clock expiry of the active claim, null after a report';
COMMENT ON COLUMN sync_execution.next_check_at IS 'Earliest authority time when an unfinished intent can be inspected again';
COMMENT ON COLUMN sync_execution.observation_reference IS 'Bounded provider request or conversation reference reported by its owner';
COMMENT ON COLUMN sync_execution.error_message IS 'Explicit bounded execution failure or recovery diagnostic';
COMMENT ON COLUMN sync_execution.created_at IS 'UTC time when application intent was accepted';
COMMENT ON COLUMN sync_execution.updated_at IS 'UTC time maintained by the execution metadata trigger';
COMMENT ON COLUMN sync_execution.deleted_at IS 'Nullable UTC soft-deletion time';

003-authority.sql:
CREATE TABLE sync_authority (
  id uuid PRIMARY KEY DEFAULT uuidv7(),
  singleton boolean NOT NULL DEFAULT true CHECK (singleton),
  generation uuid NOT NULL DEFAULT uuidv7(),
  phase varchar(20) NOT NULL DEFAULT 'recovering' CHECK (phase IN ('active', 'recovering', 'fenced')),
  recovered_source_generation uuid,
  recovery_target_generation uuid,
  restored_snapshot_at timestamptz,
  schema_revision integer NOT NULL DEFAULT 1 CHECK (schema_revision > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  UNIQUE (singleton)
);

CREATE TABLE sync_workspace_authority (
  id uuid PRIMARY KEY DEFAULT uuidv7(),
  workspace_identifier uuid NOT NULL UNIQUE,
  generation uuid NOT NULL DEFAULT uuidv7(),
  phase varchar(20) NOT NULL DEFAULT 'active' CHECK (phase IN ('active', 'fenced')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);

CREATE TABLE sync_schema_migration (
  id uuid PRIMARY KEY DEFAULT uuidv7(),
  identity varchar(200) NOT NULL UNIQUE CHECK (length(identity) > 0),
  digest varchar(64) NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);

CREATE FUNCTION set_sync_authority_updated_at()
RETURNS trigger AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_sync_authority_updated_at BEFORE UPDATE ON sync_authority
FOR EACH ROW EXECUTE FUNCTION set_sync_authority_updated_at();
CREATE TRIGGER trg_sync_workspace_authority_updated_at BEFORE UPDATE ON sync_workspace_authority
FOR EACH ROW EXECUTE FUNCTION set_sync_authority_updated_at();
CREATE TRIGGER trg_sync_schema_migration_updated_at BEFORE UPDATE ON sync_schema_migration
FOR EACH ROW EXECUTE FUNCTION set_sync_authority_updated_at();

ALTER TABLE sync_authority REPLICA IDENTITY FULL;
ALTER TABLE sync_workspace_authority REPLICA IDENTITY FULL;
ALTER TABLE sync_schema_migration REPLICA IDENTITY FULL;

ALTER TABLE sync_execution ADD COLUMN recovery_held boolean NOT NULL DEFAULT false;
ALTER TABLE sync_execution ADD COLUMN lease_generation uuid;

DROP INDEX idx_sync_execution_workspace_identifier_next_check_at_id;
CREATE INDEX idx_sync_execution_workspace_identifier_next_check_at_id
ON sync_execution (workspace_identifier, next_check_at, id)
WHERE NOT recovery_held AND deleted_at IS NULL
  AND status IN ('waiting-owner', 'executing', 'recovery-required');

COMMENT ON TABLE sync_authority IS 'Deployment identity and transactional activation fence for synchronized application writes [domain:collaboration],[team:cueloop],[project:cueloop],[service:sync]';
COMMENT ON COLUMN sync_authority.id IS 'Immutable logical authority identity retained across recovery generations';
COMMENT ON COLUMN sync_authority.singleton IS 'Singleton constraint allowing one deployment authority record';
COMMENT ON COLUMN sync_authority.generation IS 'Fresh UUID v7 invalidating old replica positions and request issuance after restore';
COMMENT ON COLUMN sync_authority.phase IS 'Active write eligibility, offline recovery, or a durable source write fence';
COMMENT ON COLUMN sync_authority.recovered_source_generation IS 'Source generation retained from the backup for verified activation fencing';
COMMENT ON COLUMN sync_authority.recovery_target_generation IS 'One destination generation allowed to activate from this durable source fence';
COMMENT ON COLUMN sync_authority.restored_snapshot_at IS 'UTC beginning of the restored consistent snapshot, or null for a new deployment';
COMMENT ON COLUMN sync_authority.schema_revision IS 'Supported authority protocol schema revision';
COMMENT ON COLUMN sync_authority.created_at IS 'UTC time when the logical authority was initialized';
COMMENT ON COLUMN sync_authority.updated_at IS 'UTC update time maintained by its trigger';
COMMENT ON COLUMN sync_authority.deleted_at IS 'UTC retirement time, or null while the authority identity is retained';

COMMENT ON TABLE sync_workspace_authority IS 'Per-workspace generation and write fence independent of other workspaces [domain:collaboration],[team:cueloop],[project:cueloop],[service:sync]';
COMMENT ON COLUMN sync_workspace_authority.id IS 'Immutable synthetic UUID v7 authority binding identity';
COMMENT ON COLUMN sync_workspace_authority.workspace_identifier IS 'Application workspace whose mutation and execution transactions share this fence';
COMMENT ON COLUMN sync_workspace_authority.generation IS 'Fresh UUID v7 binding newly issued workspace operations';
COMMENT ON COLUMN sync_workspace_authority.phase IS 'Active writes or an explicit workspace fence';
COMMENT ON COLUMN sync_workspace_authority.created_at IS 'UTC time when the workspace authority was registered';
COMMENT ON COLUMN sync_workspace_authority.updated_at IS 'UTC update time maintained by its trigger';
COMMENT ON COLUMN sync_workspace_authority.deleted_at IS 'UTC workspace retirement time, or null while active';

COMMENT ON TABLE sync_schema_migration IS 'Applied application and SDK migration identities and immutable source digests [domain:collaboration],[team:cueloop],[project:cueloop],[service:sync]';
COMMENT ON COLUMN sync_schema_migration.id IS 'Immutable synthetic UUID v7 migration record identity';
COMMENT ON COLUMN sync_schema_migration.identity IS 'Application-qualified migration identity reserved after successful commit';
COMMENT ON COLUMN sync_schema_migration.digest IS 'SHA-256 digest of the exact applied migration bytes';
COMMENT ON COLUMN sync_schema_migration.created_at IS 'UTC time when the migration committed';
COMMENT ON COLUMN sync_schema_migration.updated_at IS 'UTC update time maintained by its trigger';
COMMENT ON COLUMN sync_schema_migration.deleted_at IS 'UTC retirement time while retaining the migration identity';
COMMENT ON COLUMN sync_execution.recovery_held IS 'Restored intent requires verified provider recovery before claim eligibility';
COMMENT ON COLUMN sync_execution.lease_generation IS 'Authority generation that issued the current lease and can accept its reports';

004-restore-journal.sql:
CREATE SCHEMA cueloop_sync_recovery;

CREATE TABLE cueloop_sync_recovery.restore_attempt (
  id uuid PRIMARY KEY DEFAULT uuidv7(),
  singleton boolean NOT NULL DEFAULT true CHECK (singleton),
  source_authority_identifier uuid NOT NULL,
  source_generation uuid NOT NULL,
  target_generation uuid NOT NULL DEFAULT uuidv7(),
  archive_digest varchar(64) NOT NULL CHECK (archive_digest ~ '^[0-9a-f]{64}$'),
  manifest_digest varchar(64) NOT NULL CHECK (manifest_digest ~ '^[0-9a-f]{64}$'),
  phase varchar(20) NOT NULL DEFAULT 'prepared' CHECK (phase IN ('prepared', 'finalized')),
  schema_revision integer NOT NULL DEFAULT 1 CHECK (schema_revision = 1),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  UNIQUE (singleton)
);

CREATE FUNCTION cueloop_sync_recovery.set_restore_attempt_updated_at()
RETURNS trigger AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_restore_attempt_updated_at
BEFORE UPDATE ON cueloop_sync_recovery.restore_attempt
FOR EACH ROW EXECUTE FUNCTION cueloop_sync_recovery.set_restore_attempt_updated_at();

ALTER TABLE cueloop_sync_recovery.restore_attempt REPLICA IDENTITY FULL;

COMMENT ON TABLE cueloop_sync_recovery.restore_attempt IS 'Destination-bound recovery journal outside canonical application snapshots [domain:collaboration],[team:cueloop],[project:cueloop],[service:sync]';
COMMENT ON COLUMN cueloop_sync_recovery.restore_attempt.id IS 'Immutable UUID v7 identity for this destination restore attempt';
COMMENT ON COLUMN cueloop_sync_recovery.restore_attempt.singleton IS 'Singleton reservation preventing a second archive from replacing this database';
COMMENT ON COLUMN cueloop_sync_recovery.restore_attempt.source_authority_identifier IS 'Logical authority identity retained from the verified snapshot manifest';
COMMENT ON COLUMN cueloop_sync_recovery.restore_attempt.source_generation IS 'Source generation whose accepted receipts define the snapshot recovery boundary';
COMMENT ON COLUMN cueloop_sync_recovery.restore_attempt.target_generation IS 'Fresh generation reserved once and retained across finalization retries';
COMMENT ON COLUMN cueloop_sync_recovery.restore_attempt.archive_digest IS 'SHA-256 of the exact archive admitted to this destination';
COMMENT ON COLUMN cueloop_sync_recovery.restore_attempt.manifest_digest IS 'SHA-256 of the canonical manifest binding identity, schema, snapshot, and archive';
COMMENT ON COLUMN cueloop_sync_recovery.restore_attempt.phase IS 'Prepared reservation or atomically finalized authority and execution holds';
COMMENT ON COLUMN cueloop_sync_recovery.restore_attempt.schema_revision IS 'Supported restore-journal protocol revision';
COMMENT ON COLUMN cueloop_sync_recovery.restore_attempt.created_at IS 'UTC time when the destination reserved this restore attempt';
COMMENT ON COLUMN cueloop_sync_recovery.restore_attempt.updated_at IS 'UTC update time maintained by its trigger';
COMMENT ON COLUMN cueloop_sync_recovery.restore_attempt.deleted_at IS 'UTC retirement time while retaining the unique destination reservation';

005-workspace-transfer.sql:
CREATE TABLE sync_workspace_transfer (
  id uuid PRIMARY KEY DEFAULT uuidv7(),
  workspace_identifier uuid NOT NULL,
  binding jsonb NOT NULL CHECK (octet_length(binding::text) <= 4096),
  phase varchar(20) NOT NULL CHECK (phase IN ('fenced', 'imported', 'active')),
  manifest_digest varchar(64) CHECK (manifest_digest ~ '^[0-9a-f]{64}$'),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  CHECK (binding->>'transferIdentifier' = id::text),
  CHECK (binding->'source'->>'workspaceIdentifier' = workspace_identifier::text),
  CHECK (binding->'target'->>'workspaceIdentifier' = workspace_identifier::text),
  CHECK ((phase = 'fenced' AND manifest_digest IS NULL) OR (phase IN ('imported', 'active') AND manifest_digest IS NOT NULL))
);

CREATE TRIGGER trg_sync_workspace_transfer_updated_at
BEFORE UPDATE ON sync_workspace_transfer
FOR EACH ROW EXECUTE FUNCTION set_sync_authority_updated_at();

ALTER TABLE sync_workspace_transfer REPLICA IDENTITY FULL;

CREATE INDEX idx_sync_workspace_transfer_workspace_identifier_created_at_id
ON sync_workspace_transfer (workspace_identifier, created_at DESC, id DESC);

COMMENT ON TABLE sync_workspace_transfer IS 'Forward-only workspace handoff and destination reservation [domain:collaboration],[team:cueloop],[project:cueloop],[service:sync]';
COMMENT ON COLUMN sync_workspace_transfer.id IS 'Immutable UUID v7 identity shared by the source and destination journals';
COMMENT ON COLUMN sync_workspace_transfer.workspace_identifier IS 'Workspace reserved by this transfer for one bound destination';
COMMENT ON COLUMN sync_workspace_transfer.binding IS 'Immutable versioned source, target, and application adapter identities';
COMMENT ON COLUMN sync_workspace_transfer.phase IS 'Source fence or destination import and activation state';
COMMENT ON COLUMN sync_workspace_transfer.manifest_digest IS 'SHA-256 of the exact imported manifest, null before import';
COMMENT ON COLUMN sync_workspace_transfer.created_at IS 'UTC time when this deployment reserved the transfer';
COMMENT ON COLUMN sync_workspace_transfer.updated_at IS 'UTC time maintained by the journal trigger';
COMMENT ON COLUMN sync_workspace_transfer.deleted_at IS 'UTC retirement time while retaining the workspace reservation';
